const map=L.map('map',{zoomControl:false}).setView([-33.4372,-70.6506],17);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);
const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="32" height="40" viewBox="0 0 32 40" shape-rendering="crispEdges"><path fill="#152b38" d="M8 2h16v4h4v12h-3v12h-3v7h-6v-5h-2v5H8v-7H5V18H3V7h5z"/><path fill="#e75448" d="M8 3h16v4h4v5H4V7h4z"/><path fill="#fff3d7" d="M7 12h18v9h-3v3H10v-3H7z"/><path fill="#192e38" d="M10 14h3v3h-3zm9 0h3v3h-3z"/><path fill="#5b9fd0" d="M8 24h16v9h-5v-4h-6v4H8z"/><path fill="#f4c58e" d="M5 22h3v7H5zm19 0h3v7h-3z"/></svg>`;
const playerIcon=L.divIcon({className:'',html:`<img class="sprite" src="data:image/svg+xml,${encodeURIComponent(svg)}" alt="">`,iconSize:[32,40],iconAnchor:[16,35]});
const starIcon=L.divIcon({className:'',html:'<div class="treasure">⭐</div>',iconSize:[30,30],iconAnchor:[15,15]});
let pos=L.latLng(-33.4372,-70.6506), player=L.marker(pos,{icon:playerIcon,interactive:false}).addTo(map), treasures=[],score=0,started=false, timer=null;
const hint=document.querySelector('#hint'),place=document.querySelector('#place'),scoreEl=document.querySelector('#score'),toast=document.querySelector('#toast');
function show(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove('show'),1800)}
function spawn(){treasures.forEach(m=>map.removeLayer(m));treasures=[];for(let i=0;i<8;i++){let angle=Math.random()*Math.PI*2,dist=70+Math.random()*230;let p=L.latLng(pos.lat+Math.cos(angle)*dist/111320,pos.lng+Math.sin(angle)*dist/(111320*Math.cos(pos.lat*Math.PI/180)));treasures.push(L.marker(p,{icon:starIcon,interactive:false}).addTo(map))}}
function start(latlng,label){pos=L.latLng(latlng);player.setLatLng(pos);map.setView(pos,17);score=0;scoreEl.textContent='0';started=true;place.textContent=label;hint.textContent='Muévete por tu ciudad y encuentra las estrellas.';spawn()}
function geolocate(){if(!navigator.geolocation){hint.textContent='Este navegador no permite GPS. Toca el mapa para elegir un lugar.';return}hint.textContent='Buscando tu ubicación…';navigator.geolocation.getCurrentPosition(p=>start([p.coords.latitude,p.coords.longitude],'TU BARRIO · CHILE'),()=>{hint.textContent='No pudimos obtener tu ubicación. Toca el mapa para elegir un punto.'},{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
document.querySelector('#gps').addEventListener('click',geolocate);document.querySelector('#reset').addEventListener('click',()=>{start(pos,'NUEVA AVENTURA');show('¡A explorar!')});
map.on('click',e=>{if(!started)start(e.latlng,'PUNTO ELEGIDO EN EL MAPA')});
function move(dir){if(!started){hint.textContent='Primero usa el botón ⌖ o toca un punto del mapa.';return}let step=12,lat=step/111320,lng=step/(111320*Math.cos(pos.lat*Math.PI/180));if(dir==='up')pos.lat+=lat;if(dir==='down')pos.lat-=lat;if(dir==='left')pos.lng-=lng;if(dir==='right')pos.lng+=lng;player.setLatLng(pos);map.panTo(pos,{animate:false});for(let i=treasures.length-1;i>=0;i--){if(pos.distanceTo(treasures[i].getLatLng())<24){map.removeLayer(treasures[i]);treasures.splice(i,1);score++;scoreEl.textContent=score;show('¡Encontraste una estrella!');if(!treasures.length){spawn();show('¡Encontraste todas! Hay más cerca.')}}}}
document.querySelectorAll('[data-dir]').forEach(b=>{let release=()=>{clearInterval(timer);timer=null};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);move(b.dataset.dir);release();timer=setInterval(()=>move(b.dataset.dir),140)});b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release)});
document.addEventListener('keydown',e=>{const dirs={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',s:'down',a:'left',d:'right'};if(dirs[e.key]){e.preventDefault();move(dirs[e.key])}});
